use leptos::html;
use leptos::prelude::*;
use leptos_ui::clx;

mod components {
    use super::*;

    // The table wrapper is not generated by `clx!` because callers that
    // virtualize their rows need the scroll container's `NodeRef`.
    //
    // `overflow-anchor:none` is part of the virtualization contract: a
    // virtualized body moves its top spacer when the window advances, and the
    // browser's scroll anchoring would "correct" `scrollTop` for that shift on
    // every scroll event. The correction feeds the next window calculation and
    // sends the list straight to one end instead of following the pointer.
    //
    // This wrapper (not `Table`) is the scroll port: it is the only element
    // sized to the viewport, so a wide table scrolls horizontally here instead
    // of pushing the page sideways on a phone.
    #[component]
    pub fn TableWrapper(
        #[prop(into, optional)] class: String,
        #[prop(optional)] node_ref: NodeRef<html::Div>,
        children: Children,
    ) -> impl IntoView {
        let merged_class = tw_merge::tw_merge!(
            "ferris-table-wrapper relative w-full max-w-full h-full overflow-auto overscroll-x-contain rounded-xl [overflow-anchor:none]",
            class
        );

        view! {
            <div class=merged_class data-name="TableWrapper" node_ref=node_ref>
                {children()}
            </div>
        }
    }

    // `w-full` only; the component deliberately sets no `min-w`, so the table
    // can be narrower than its wrapper and any horizontal overflow is decided
    // by the content (cells use `whitespace-nowrap`) inside the scroll port.
    clx! {Table, table, "ferris-table w-full caption-bottom text-sm"}
    clx! {TableCaption, caption, "ferris-table__caption mt-4 text-sm"}
    clx! {TableHeader, thead, "ferris-table__header [&_tr]:border-b"}
    clx! {TableRow, tr, "ferris-table__row border-b transition-colors"}
    clx! {TableBody, tbody, "ferris-table__body [&_tr:last-child]:border-0"}
    clx! {TableCell, td, "ferris-table__cell px-3 py-2 align-middle [&:has([role=checkbox])]:pr-0 [&:has([role=checkbox])]:pl-3"}
    clx! {TableFooter, tfoot, "ferris-table__footer font-medium border-t [&>tr]:last:border-b-0"}
    clx! {CardContent, div, "pt-4"}
    clx! {CardFooter, div, "mt-4", "flex items-center justify-end"}
}

pub use components::*;

/// A column header. `scope="col"` is set in one place so every table in the
/// Desk is announced column by column instead of as an undifferentiated grid.
#[component]
pub fn TableHead(#[prop(into, optional)] class: String, children: Children) -> impl IntoView {
    let merged_class = tw_merge::tw_merge!(
        "ferris-table__head h-10 px-3 text-left align-middle font-medium whitespace-nowrap [&:has([role=checkbox])]:pr-0",
        class
    );
    view! {
        <th scope="col" class=merged_class>
            {children()}
        </th>
    }
}
